#include <iostream>
#include <cmath>
using namespace std;

int main() {
    int h, n;
    cin >> h >> n;

    long long l = 1, r = (1LL << h);
    long long res = 0;
    int dir_flag = 0;

    while (l < r) {
        long long mid = (l + r) / 2;
        if (n <= mid) {
            if (dir_flag == 0) {
                res += 1;
                dir_flag = 1;
            } else {
                res += (1LL << h);
            }
            r = mid;
        } else {
            if (dir_flag == 1) {
                res += 1;
                dir_flag = 0;
            } else {
                res += (1LL << h);
            }
            l = mid + 1;
        }
        h -= 1;
    }

    cout << res << "\n";
    return 0;
}
